namespace Wsg.Switcher;

internal sealed class HelpForm : Form
{
    internal HelpForm(bool light) {
        Text = "Help • WSG OpenXR FG Switcher"; Font = new Font("Segoe UI", 10);
        ClientSize = new Size(780, 455); MinimumSize = new Size(700, 430);
        StartPosition = FormStartPosition.CenterParent; ShowInTaskbar = false;
        var topics = new (string Title, string Text)[] {
            ("djules 0.2.14.1", "More options includes Hybrid, optional Hybrid depth search, 25% flow resolution and overlay detail controls. Hybrid uses game motion vectors from DLSS and adds GPU work. Depth search can improve thin nearby objects, with extra cost at high VR resolutions. Both are off by default.\r\n\r\nThe overlay can show Hybrid status, latency and the multiplier in three sizes. HYBRID OK in the headset is evidence from the provider; selecting Hybrid alone does not confirm support.\r\n\r\nFresh djules presets use FidelityFX; existing presets keep their saved choice. WSG applies a setup before launch. OFXR's own tray also offers live controls while playing."),
            ("Startup & launch scripts", "Startup in the sidebar saves a default game and mod. It uses that game's saved version and settings. Apply on launch and Start in tray are independent, optional choices. Errors bring the window forward.\r\n\r\nLaunch with --tray (or the existing --minimized / --start-minimized aliases) to open in the tray for this session. Restore WSG from its tray icon.\r\n\r\nFor a launch script, use --apply-default and wait for the process to exit with code 0 before launching the game. This applies once and exits without stopping the selected provider. No WSG background process remains. The README has a PowerShell example and explicit game/provider arguments.\r\n\r\nExit codes: 0 = applied, 1 = failed, 2 = invalid arguments, 3 = WSG already running. Exit an existing WSG instance first. An apply result is written to startup-result.json in the Data folder.\r\n\r\nWhile hidden, routine checks stop. Opening WSG refreshes the setup, and changes are checked again before applying. Only pending removal or an explicitly queued Exit continues checking while hidden."),
            ("Rescan, updates & recovery", "Rescan setup\r\nRereads installed mods, saved settings and OpenXR registrations. Use it after changing settings in a provider's own app. It does not switch the active provider.\r\n\r\nCheck for updates\r\nRefreshes the signed mod list and checks official releases. New compatible mod versions can be downloaded without updating WSG. Choose a version, then Download & install. Updates never switch your selected setup automatically. WSG app updates are checked separately.\r\n\r\nRecover operation\r\nRestores the previous setup after an interrupted installation, removal or switch. It is disabled when there is nothing to recover. Close games and provider editors before recovery; this can restore files and registrations. It does not reset your PC or all your preferences."),
            ("Switching mods", "1. Choose a Game preset and a mod.\r\n2. Install it if needed, then choose your settings.\r\n3. Close all OpenXR games and click Apply.\r\n4. Start the game normally.\r\n\r\nGreen and Applied identify the verified setup. The blue outline marks the tab you are editing. Selecting a tab does not change the active setup.\r\n\r\nReady for next launch confirms saved settings and registrations. Use the provider's in-game overlay to confirm FG is running. Restart the game after switching; toggling VR mode is not enough.\r\n\r\nOnly one setup is active at a time. Off disables the managed frame-generation providers."),
            ("Settings & provider apps", "WSG saves the controls shown here in each game preset. Apply writes those settings; other supported tuning is preserved.\r\n\r\nMore options contains flow resolution, performance preferences and experimental VectorXR coexistence.\r\n\r\nOFXR: Apply starts its tray. Right-click the notification-area icon for the full settings menu.\r\n\r\nVectorXR: Start VectorXR app opens its editor; this does not apply a WSG setup. Its desktop app need not stay open for its layer to work.\r\n\r\nAfter editing settings in the provider's app, close its editor and use Rescan setup before applying here. Native DLSS requires compatible NVIDIA hardware and game support."),
            ("Installation & game profiles", "Expand Manage installation to see the destination, find an existing installation, or remove a version. Mod folder in the sidebar changes the root for future installs.\r\n\r\nVectorXR's section also shows the game executable and location. Apply prepares its FG profile by executable name. OFXR settings are global while that preset is applied.\r\n\r\nVectorXR uses its official installer and uninstaller; Windows may ask for administrator permission. Leave the provider app closed afterwards.\r\n\r\nRemoval deletes verified provider files and empty installation folders. Presets, notes and unrelated files are retained. Temporary recovery files are deleted after completion. Off only disables FG."),
            ("Compatibility", "Compatibility checks use saved configuration for the selected game. Expand the summary to see the findings. New warnings and conflicts open automatically.\r\n\r\nConfirmed conflicts block Apply. Fix the setting in the provider's own interface, save, then Rescan setup. WSG does not change OpenXR Toolkit settings.\r\n\r\nToolkit Turbo and retained VectorXR Turbo should not run together. VectorXR suppresses its own Turbo while its FG runs; Toolkit Turbo alongside VectorXR FG is shown as a warning.\r\n\r\nUnknown settings are reported as unchecked. These checks do not measure in-game toggles, runtime motion smoothing or every possible layer interaction. Retained VectorXR enhancements remain experimental."),
            ("Test notes & exiting", "Test notes record what you observed with a setup. Repeat the same scene with another mod or Off, then save another note. FPS figures are optional and entered manually; there is no automatic benchmark. Export all runs to CSV from Test notes.\r\n\r\nClosing or minimizing keeps WSG in the notification area. Explicit Exit cleans up providers after games and editors close. If an operation is busy, Exit queues until it finishes.\r\n\r\nAn interrupted installation or removal keeps recovery records for the next launch. Use Recover operation to resume recovery. Diagnostics shows technical details.")
        };
        var layout = new TableLayoutPanel { Dock = DockStyle.Fill, Padding = new Padding(18), ColumnCount = 2, RowCount = 2 };
        layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 205)); layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100)); layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 45)); Controls.Add(layout);
        var list = new ListBox { Dock = DockStyle.Fill, IntegralHeight = false, AccessibleName = "Help topics" };
        var text = new TextBox { Dock = DockStyle.Fill, Multiline = true, ReadOnly = true, ScrollBars = ScrollBars.Vertical, BorderStyle = BorderStyle.None,
            Margin = new Padding(16, 0, 0, 8), AccessibleName = "Help topic" };
        foreach (var topic in topics) list.Items.Add(topic.Title);
        list.SelectedIndexChanged += (_, _) => { if (list.SelectedIndex >= 0) { text.Text = topics[list.SelectedIndex].Text; text.SelectionStart = 0; } };
        layout.Controls.Add(list, 0, 0); layout.Controls.Add(text, 1, 0);
        var close = new ThemeButton { Text = "Close", DialogResult = DialogResult.Cancel, Size = new Size(100, 34), Anchor = AnchorStyles.Right | AnchorStyles.Bottom };
        layout.Controls.Add(close, 1, 1); CancelButton = close;
        WindowTheme.Bind(this, light); list.SelectedIndex = 0;
    }
}
